{"query":"
          query seasons($configLeagueName: String!, $sort: String) {
            seasons(configLeagueName: $configLeagueName, sort: $sort) {
              id
              name
              years
              configLeagueName
              configSeasonStartYear
            }
          }
        ","variables":{"configLeagueName":"allsvenskan","sort":"DESC"},"operationName":"seasons"}

{"query":"
          query teamNews($abbrv: String!, $limit: Int!) {
            teamNews(abbrv: $abbrv, limit: $limit) {
              news {
                id
                abbrv
                title
                description
                dateTime
                image
                articleUrl
                logoImageUrl
                iconUrl
              }
            }
          }
        ","variables":{"abbrv":"allsvenskan","limit":7},"operationName":"teamNews"}
